templates.home:
{{template "top" .}}<h1>{{.businessName}}</h1>{{with .tagline}}<p class="muted">{{.}}</p>{{end}}
<div class="chips"><a class="chip{{if not .category}} on{{end}}" href="/{{if eq .lang "ar"}}?lang=ar{{end}}">{{.t.all}}</a>{{range .categories}}<a class="chip{{if .on}} on{{end}}" href="/?c={{.key}}{{if eq $.lang "ar"}}&lang=ar{{end}}">{{.name}}</a>{{end}}</div>
{{range .groups}}{{if .name}}<h2>{{.name}}</h2>{{end}}
<div class="grid">{{range .items}}<a class="card" href="/item/{{.id}}{{if eq $.lang "ar"}}?lang=ar{{end}}"><div class="img">{{if .image}}<img src="{{.image}}?w=480" alt="{{.name}}" loading="lazy">{{else}}{{.name}}{{end}}</div>
<div class="body"><div>{{.name}}</div>{{with .duration}}<div class="muted">{{.}}</div>{{end}}<div class="price">{{$.t.from}} AED {{.price}} <span class="muted">{{.unit}}</span></div></div></a>{{end}}</div>{{end}}
{{template "bottom" .}}

templates.item:
{{template "top" .}}<div class="two"><div>
<div class="photo">{{if .item.image}}<img src="{{.item.image}}?w=960" alt="{{.item.name}}">{{else}}{{.item.name}}{{end}}</div>
{{if .item.moreImages}}<div class="thumbs">{{range .item.moreImages}}<div class="photo"><img src="{{.}}?w=480" alt="{{$.item.name}}" loading="lazy"></div>{{end}}</div>{{end}}
<h1>{{.item.name}}</h1><p class="muted">{{.item.category}}{{with .item.duration}} · {{$.t.duration}}: {{.}}{{end}}</p>
<p>{{.item.description}}</p>{{with .item.included}}<p><strong>{{$.t.included}}:</strong> {{.}}</p>{{end}}
{{if .item.isDeparture}}<p class="price">{{.t.adult}} AED {{.item.priceAdult}}{{with .item.priceChild}} · {{$.t.child}} AED {{.}}{{end}}</p>
{{else}}<p class="price">AED {{.item.priceDay}} {{.t.per_day}}{{with .item.priceWeek}} · AED {{.}} {{$.t.per_week}}{{end}}</p>
{{with .item.minDays}}<p class="muted">{{$.t.min_days}}: {{.}} {{$.t.days}}</p>{{end}}{{with .item.security}}<p class="muted">{{$.t.security_deposit}}: AED {{.}}</p>{{end}}{{end}}
<p class="muted">{{.t.vat_included}}</p></div>
<form id="reserve" method="get" action="/checkout" class="panel" style="margin-top:0">
<input type="hidden" name="item" value="{{.item.id}}">{{if eq .lang "ar"}}<input type="hidden" name="lang" value="ar">{{end}}
{{with .error}}<p class="error">{{.}}</p>{{end}}
{{if .item.isDeparture}}<h3 style="margin-top:0">{{.t.choose_departure}}</h3>
{{if .occurrences}}<div class="slots">{{range .occurrences}}<label class="slot{{if .full}} off{{end}}"><input type="radio" name="when" value="{{.key}}" required{{if .full}} disabled{{end}}>
<span>{{.label}}</span><span class="muted">{{if .full}}{{$.t.sold_out}}{{else}}{{.left}} {{$.t.seats_left}} · AED {{.price}}{{end}}</span></label>{{end}}</div>
{{else}}<p class="muted">{{.t.no_departures}}</p>{{end}}
<div class="pair"><div><label for="adults">{{.t.adults}}</label><div class="count"><button type="button" class="secondary" data-step="-1">−</button><input id="adults" name="adults" type="number" min="1" max="99" value="2" required><button type="button" class="secondary" data-step="1">+</button></div></div>
<div><label for="children">{{.t.children}}</label><div class="count"><button type="button" class="secondary" data-step="-1">−</button><input id="children" name="children" type="number" min="0" max="99" value="0"><button type="button" class="secondary" data-step="1">+</button></div></div></div>
{{else}}<div class="pair"><div><label for="start">{{.t.start_date}}</label><input id="start" name="start" type="date" min="{{.today}}" max="{{.last}}" required></div>
<div><label for="end">{{.t.end_date}}</label><input id="end" name="end" type="date" min="{{.today}}" required></div></div>
<label for="qty">{{.t.quantity}}</label><div class="count"><button type="button" class="secondary" data-step="-1">−</button><input id="qty" name="qty" type="number" min="1" max="{{.item.stock}}" value="1" required><button type="button" class="secondary" data-step="1">+</button></div>
{{end}}
{{if .extras}}<h3>{{.t.extras}}</h3>{{range .extras}}<label class="pick"><input type="checkbox" name="x{{.id}}" value="1"><span>{{.name}} <span class="muted">+ AED {{.price}} {{.per}}</span></span></label>{{end}}{{end}}
<div id="summary" hidden style="margin:16px 0"></div>
<button>{{.t.reserve}}</button></form></div>
<script>
(function(){
  var form=document.getElementById('reserve'),box=document.getElementById('summary'),timer=null,turn=0;
  function line(label,value,cls){var d=document.createElement('div');d.className='row '+(cls||'');var a=document.createElement('span'),b=document.createElement('span');a.textContent=label;b.textContent=value;d.appendChild(a);d.appendChild(b);return d}
  // The summary is for display only; the server works the price out again when the reservation is made.
  function update(){var mine=++turn;fetch('/api/availability?'+new URLSearchParams(new FormData(form)).toString()).then(function(r){return r.json()}).then(function(j){
    if(mine!==turn)return;box.textContent='';box.hidden=!j.complete;if(!j.complete)return;
    var p=document.createElement('p');p.className=j.available?'ok':'error';p.textContent=j.message;box.appendChild(p);
    (j.rows||[]).forEach(function(r){box.appendChild(line(r.label,r.value,r.cls))});}).catch(function(){box.hidden=true})}
  function soon(){clearTimeout(timer);timer=setTimeout(update,250)}
  form.addEventListener('input',soon);form.addEventListener('change',soon);
  form.querySelectorAll('button[data-step]').forEach(function(b){b.addEventListener('click',function(){var i=b.parentNode.querySelector('input');
    var v=(parseInt(i.value,10)||0)+parseInt(b.getAttribute('data-step'),10),lo=parseInt(i.min,10)||0,hi=parseInt(i.max,10)||999;i.value=Math.max(lo,Math.min(hi,v));soon()})});
  var s=document.getElementById('start'),e=document.getElementById('end');
  if(s&&e)s.addEventListener('change',function(){e.min=s.value;if(e.value&&e.value<s.value)e.value=s.value});
})();
</script>
{{template "bottom" .}}

templates.reservations:
{{template "top" .}}<h1>{{.t.my_reservations}}</h1>
{{if .reservations}}{{range .reservations}}<a class="card" style="margin:12px 0" href="/reservations/{{.id}}{{if eq $.lang "ar"}}?lang=ar{{end}}"><div class="body">
<div class="row"><strong>{{$.t.reservation}} #{{.id}}</strong><span>{{.status}}</span></div><div>{{.item}}</div>
<div class="row muted"><span>{{.when}}</span><span>AED {{.total}}</span></div></div></a>{{end}}
{{else}}<p class="muted">{{.t.no_reservations}}</p><p><a class="btn" href="/{{if eq .lang "ar"}}?lang=ar{{end}}">{{.t.home}}</a></p>{{end}}
{{template "bottom" .}}

scripts.home:
function langOf(req) { return req.query.lang === 'ar' ? 'ar' : 'en'; }
function texts(lang) {
  const t = {};
  for (const r of db.query('SELECT key, en, ar FROM texts')) t[r.key] = (lang === 'ar' ? r.ar : r.en) || r.en;
  return t;
}
function business() { return db.query('SELECT * FROM business ORDER BY id LIMIT 1')[0]; }
function round2(n) { return Math.round(n * 100) / 100; }
function money(n) { return round2(n || 0).toFixed(2); }
function loc(row, field, lang) { return lang === 'ar' && row[field + '_ar'] ? row[field + '_ar'] : row[field]; }

// Dates are local UAE dates as text, 'YYYY-MM-DD', and times 'HH:MM'; they compare correctly as strings.
// The UAE is UTC+4 all year, so "now" in Dubai is UTC plus four hours.
function nowDubai() {
  const iso = new Date(Date.now() + 4 * 3600 * 1000).toISOString();
  return {date: iso.slice(0, 10), time: iso.slice(11, 16)};
}
// Milliseconds (UTC midnight) of a 'YYYY-MM-DD' date, or null when it is not a real date.
function parts(s) {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s || '');
  if (!m) return null;
  const ms = Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3]));
  return new Date(ms).toISOString().slice(0, 10) === s ? ms : null;
}
function addDays(s, n) { return new Date(parts(s) + n * 86400000).toISOString().slice(0, 10); }
function dayDiff(a, b) { return Math.round((parts(b) - parts(a)) / 86400000); }
const WEEKDAYS = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'];
const DAY_NAMES = {en: ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'], ar: ['الأحد', 'الاثنين', 'الثلاثاء', 'الأربعاء', 'الخميس', 'الجمعة', 'السبت']};
const MONTH_NAMES = {en: ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'],
  ar: ['يناير', 'فبراير', 'مارس', 'أبريل', 'مايو', 'يونيو', 'يوليو', 'أغسطس', 'سبتمبر', 'أكتوبر', 'نوفمبر', 'ديسمبر']};
function showDate(s, lang) {
  const ms = parts(s);
  if (ms === null) return s || '';
  const d = new Date(ms), l = lang === 'ar' ? 'ar' : 'en';
  return DAY_NAMES[l][d.getUTCDay()] + ' ' + d.getUTCDate() + ' ' + MONTH_NAMES[l][d.getUTCMonth()] + ' ' + d.getUTCFullYear();
}
// A whole number from a form or query value; def when it is missing, -1 when it is not a whole number.
function whole(v, def) {
  if (v === undefined || v === null || v === '') return def;
  const n = Number(v);
  return Number.isInteger(n) ? n : -1;
}
function errorText(t, key, n) { return (t[key] || t.error_departure).replace(/\{n\}/g, String(n || 0)); }
function lineLabel(l, lang) { return (lang === 'ar' && l.name_ar ? l.name_ar : l.name) + (l.qty > 1 ? ' × ' + l.qty : ''); }

function page(req, extra) {
  const lang = langOf(req), b = business(), qs = [];
  for (const k in req.query) if (k !== 'lang' && k !== 'error' && k !== 'n') qs.push(encodeURIComponent(k) + '=' + encodeURIComponent(req.query[k]));
  const mine = qs.concat(lang === 'ar' ? ['lang=ar'] : []);
  const base = {lang: lang, dir: lang === 'ar' ? 'rtl' : 'ltr', t: texts(lang), user: req.user, business: b,
    businessName: loc(b, 'name', lang), tagline: loc(b, 'tagline', lang), licence: b.licence || '',
    here: req.path + (mine.length ? '?' + mine.join('&') : ''),
    langUrl: req.path + '?' + qs.concat(['lang=' + (lang === 'ar' ? 'en' : 'ar')]).join('&'),
    wa: (b.whatsapp || '').replace(/[^0-9]/g, '')};
  for (const k in extra) base[k] = extra[k];
  return base;
}


// GET /  ?c=<category>  Items by category with "from" prices.
function handle(req) {
  const lang = langOf(req), t = texts(lang), cat = req.query.c || '';
  const lowest = {};
  for (const r of db.query('SELECT item_id, MIN(price) AS p FROM departures WHERE active = 1 AND price IS NOT NULL GROUP BY item_id')) lowest[r.item_id] = r.p;
  const categories = [], groups = [], seen = {};
  for (const i of db.query('SELECT * FROM items WHERE active = 1 ORDER BY id')) {
    const key = i.category || '';
    if (!seen[key]) {
      seen[key] = {key: key, name: loc(i, 'category', lang) || key, on: key === cat, items: []};
      if (key) categories.push(seen[key]);
      if (!cat || cat === key) groups.push(seen[key]);
    }
    let price = i.mode === 'departure' ? (i.price_adult || 0) : (i.price_day || 0);
    if (i.mode === 'departure' && lowest[i.id] !== undefined && lowest[i.id] < price) price = lowest[i.id];
    seen[key].items.push({id: i.id, name: loc(i, 'name', lang), image: i.image, price: money(price), unit: i.mode === 'departure' ? t.per_person : t.per_day,
      duration: loc(i, 'duration', lang) || ''});
  }
  return {template: 'home', data: page(req, {categories: categories, groups: groups, category: cat})};
}

scripts.item:
function langOf(req) { return req.query.lang === 'ar' ? 'ar' : 'en'; }
function texts(lang) {
  const t = {};
  for (const r of db.query('SELECT key, en, ar FROM texts')) t[r.key] = (lang === 'ar' ? r.ar : r.en) || r.en;
  return t;
}
