function dayDiff(a, b) { return Math.round((parts(b) - parts(a)) / 86400000); }
const WEEKDAYS = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'];
const DAY_NAMES = {en: ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'], ar: ['الأحد', 'الاثنين', 'الثلاثاء', 'الأربعاء', 'الخميس', 'الجمعة', 'السبت']};
const MONTH_NAMES = {en: ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'],
  ar: ['يناير', 'فبراير', 'مارس', 'أبريل', 'مايو', 'يونيو', 'يوليو', 'أغسطس', 'سبتمبر', 'أكتوبر', 'نوفمبر', 'ديسمبر']};
function showDate(s, lang) {
  const ms = parts(s);
  if (ms === null) return s || '';
  const d = new Date(ms), l = lang === 'ar' ? 'ar' : 'en';
  return DAY_NAMES[l][d.getUTCDay()] + ' ' + d.getUTCDate() + ' ' + MONTH_NAMES[l][d.getUTCMonth()] + ' ' + d.getUTCFullYear();
}
// A whole number from a form or query value; def when it is missing, -1 when it is not a whole number.
function whole(v, def) {
  if (v === undefined || v === null || v === '') return def;
  const n = Number(v);
  return Number.isInteger(n) ? n : -1;
}
function errorText(t, key, n) { return (t[key] || t.error_departure).replace(/\{n\}/g, String(n || 0)); }
function lineLabel(l, lang) { return (lang === 'ar' && l.name_ar ? l.name_ar : l.name) + (l.qty > 1 ? ' × ' + l.qty : ''); }

function page(req, extra) {
  const lang = langOf(req), b = business(), qs = [];
  for (const k in req.query) if (k !== 'lang' && k !== 'error' && k !== 'n') qs.push(encodeURIComponent(k) + '=' + encodeURIComponent(req.query[k]));
  const mine = qs.concat(lang === 'ar' ? ['lang=ar'] : []);
  const base = {lang: lang, dir: lang === 'ar' ? 'rtl' : 'ltr', t: texts(lang), user: req.user, business: b,
    businessName: loc(b, 'name', lang), tagline: loc(b, 'tagline', lang), licence: b.licence || '',
    here: req.path + (mine.length ? '?' + mine.join('&') : ''),
    langUrl: req.path + '?' + qs.concat(['lang=' + (lang === 'ar' ? 'en' : 'ar')]).join('&'),
    wa: (b.whatsapp || '').replace(/[^0-9]/g, '')};
  for (const k in extra) base[k] = extra[k];
  return base;
}

// A departure row runs on its own date, or, when date is empty, on its weekdays ('daily' or e.g. 'fri,sat').
function runsOn(dep, date) {
  if (dep.date) return dep.date === date;
  const w = (dep.weekdays || 'daily').toLowerCase();
  return w.indexOf('daily') >= 0 || w.indexOf(WEEKDAYS[new Date(parts(date)).getUTCDay()]) >= 0;
}
// Nothing is counted down: seats and stock in use are added up from the reservations that hold them
// (pending, confirmed, completed, no_show), so a cancelled, failed, expired or refunded reservation frees them by itself.
function seatsTaken(depId, date, exceptId) {
  return db.query(`SELECT COALESCE(SUM(adults + children), 0) AS n FROM reservations WHERE departure_id = ? AND start_date = ? AND id <> ?
    AND status IN ('pending', 'confirmed', 'completed', 'no_show')`, depId, date, exceptId || 0)[0].n;
}
// Units of a rental item free on every day from start to end: stock minus the busiest day in that range.
// The return day counts as taken.
function rangeLeft(item, start, end, exceptId) {
  const rows = db.query(`SELECT start_date, end_date, quantity FROM reservations WHERE item_id = ? AND mode = 'range' AND id <> ?
    AND start_date <= ? AND end_date >= ? AND status IN ('pending', 'confirmed', 'completed', 'no_show')`, item.id, exceptId || 0, end, start);
  let busiest = 0;
  for (let d = start; d <= end; d = addDays(d, 1)) {
    let n = 0;
    for (const r of rows) if (r.start_date <= d && r.end_date >= d) n += r.quantity;
    if (n > busiest) busiest = n;
  }
  return (item.stock || 0) - busiest;
}
// Price of one unit for a number of days: full weeks at the weekly price when there is one, never more than one more full week.
function rentalPrice(item, days) {
  const day = item.price_day || 0;
  if (!item.price_week) return day * days;
  const weeks = Math.floor(days / 7);
  return Math.min(weeks * item.price_week + (days % 7) * day, (weeks + 1) * item.price_week);
}
function extrasFor(item) {
  return db.query(`SELECT * FROM extras WHERE active = 1 AND (item_id = ? OR (item_id IS NULL AND (category = ? OR category IS NULL OR category = ''))) ORDER BY id`,
    item.id, item.category || '');
}
// Upcoming departures of a tour within the bookable period, with seats left.
function occurrences(item, b, lang, limit) {
  const now = nowDubai(), ahead = b.days_ahead > 0 ? b.days_ahead : 60;
  const deps = db.query('SELECT * FROM departures WHERE item_id = ? AND active = 1 ORDER BY time, id', item.id);
  const taken = {};
  for (const r of db.query(`SELECT departure_id, start_date, SUM(adults + children) AS n FROM reservations WHERE item_id = ? AND mode = 'departure'
    AND start_date >= ? AND status IN ('pending', 'confirmed', 'completed', 'no_show') GROUP BY departure_id, start_date`, item.id, now.date)) {
    taken[r.departure_id + '_' + r.start_date] = r.n;
  }
  const out = [];
  for (let i = 0; i <= ahead && out.length < limit; i++) {
    const date = addDays(now.date, i);
    for (const d of deps) {
      if (!runsOn(d, date) || (i === 0 && d.time <= now.time)) continue;
      const key = d.id + '_' + date, left = d.capacity - (taken[key] || 0);
      out.push({key: key, departure_id: d.id, date: date, time: d.time, label: showDate(date, lang) + ' · ' + d.time, left: left, full: left <= 0,
        priceNum: d.price === null ? item.price_adult : d.price, price: money(d.price === null ? item.price_adult : d.price)});
    }
  }
  return out;
}

// Checks one request against the database and prices it. f holds strings as sent by the browser:
// tours: when ('<departure id>_<date>'), adults, children; rentals: start, end, qty; extras: x<extra id> = '1'.
// Returns {ok: true, lines, total, vat, online, ...} or {ok: false, error: '<texts key>', n}. Prices never come from the browser.
function quote(item, f, b, exceptId) {
  const now = nowDubai(), ahead = b.days_ahead > 0 ? b.days_ahead : 60, last = addDays(now.date, ahead);
  const en = texts('en'), ar = texts('ar');
  const q = {ok: false, complete: true, error: '', n: 0, mode: item.mode, left: 0, departure_id: null, start: '', end: '', time: '', days: 1,
    adults: 0, children: 0, qty: 1, lines: [], extras: []};
  const fail = (key, n) => { q.error = key; q.n = n || 0; return q; };
  let people = 0;
  if (item.mode === 'departure') {
    const m = /^(\d+)_(\d{4}-\d{2}-\d{2})$/.exec(f.when || '');
    if (!m) { q.complete = false; return fail('error_choose_departure'); }
    const dep = db.query('SELECT * FROM departures WHERE id = ? AND item_id = ? AND active = 1', Number(m[1]), item.id)[0];
    const date = m[2];
    if (!dep || parts(date) === null || !runsOn(dep, date) || date < now.date || date > last || (date === now.date && dep.time <= now.time)) return fail('error_departure');
    q.adults = whole(f.adults, 1); q.children = whole(f.children, 0);
    if (!(q.adults >= 1 && q.adults <= 99 && q.children >= 0 && q.children <= 99)) return fail('error_people');
    people = q.adults + q.children;
    q.departure_id = dep.id; q.start = date; q.end = date; q.time = dep.time;
    q.left = dep.capacity - seatsTaken(dep.id, date, exceptId);
    if (q.left < people) return fail('error_seats', Math.max(0, q.left));
    const adult = dep.price === null ? (item.price_adult || 0) : dep.price;
