function whenText(r, lang, t) {
  if (r.mode === 'departure') return showDate(r.start_date, lang) + ', ' + r.time;
  return showDate(r.start_date, lang) + ' – ' + showDate(r.end_date, lang) + ' (' + r.days + ' ' + (r.days === 1 ? t.day : t.days) + ')';
}
function guestsText(r, t) {
  if (r.mode === 'departure') return t.adults + ': ' + r.adults + (r.children > 0 ? ', ' + t.children + ': ' + r.children : '');
  return t.quantity + ': ' + r.quantity;
}
// The last moment a customer may cancel on the site, as UTC milliseconds: the start (UAE time) minus the free-cancellation hours.
function cancelDeadline(r, b) {
  const hm = r.mode === 'departure' && /^\d{2}:\d{2}$/.test(r.time || '') ? r.time.split(':') : ['00', '00'];
  return parts(r.start_date) + (Number(hm[0]) * 60 + Number(hm[1])) * 60000 - 4 * 3600 * 1000 - (b.free_cancel_hours || 0) * 3600 * 1000;
}
function canCancel(r, b) { return (r.status === 'pending' || r.status === 'confirmed') && Date.now() < cancelDeadline(r, b); }
function deadlineText(r, b, lang) {
