  const lang = r.lang === 'ar' ? 'ar' : 'en', t = texts(lang), b = business();
  const item = db.query('SELECT name, name_ar FROM items WHERE id = ?', r.item_id)[0] || {name: r.item_name};
  const v = {id: r.id, name: r.customer_name, business: loc(b, 'name', lang), item: loc(item, 'name', lang), when: whenText(r, lang, t), guests: guestsText(r, t),
    total: money(r.total), paid: money(r.paid_amount), balance: money(r.balance_due), whatsapp: b.whatsapp ? 'WhatsApp: ' + b.whatsapp : '',
    link: origin + '/reservations/' + r.id + '/voucher' + (lang === 'ar' ? '?lang=ar' : ''),
    deposit: r.security_deposit > 0 ? t.email_deposit.replace(/\{amount\}/g, money(r.security_deposit)) + '\n' : '',
    cancel: canCancel(r, b) ? t.email_cancel.replace(/\{until\}/g, deadlineText(r, b, lang)) + '\n' : ''};
  const fill = (s) => (s || '').replace(/\{(\w+)\}/g, (m, k) => v[k] === undefined ? m : String(v[k]));
