// POST /reservations/:id/cancel (signed in): the customer cancels inside the free-cancellation window.
// Scripts cannot refund a card: the owner is told how much to refund in Stripe, and on_payment records the refund when it is made.
function handle(req) {
  const id = Number(req.params.id), b = business();
  const r = db.query('SELECT * FROM reservations WHERE id = ? AND user_id = ?', id, req.user.id)[0];
  if (!r) return {text: 'Not found', status: 404};
  const ql = r.lang === 'ar' ? '&lang=ar' : '';
  if (!canCancel(r, b)) return {redirect: '/reservations/' + id + (r.lang === 'ar' ? '?lang=ar' : '')};
  db.exec("UPDATE reservations SET status = 'cancelled' WHERE id = ? AND user_id = ?", id, req.user.id); // frees the seats or stock
  r.status = 'cancelled';
  mailCustomer(r, 'cancel', req.origin);
  try {
    notify.owner({subject: ('Cancelled by customer #' + id + ': ' + r.item_name + ', ' + r.start_date + (r.paid_amount > 0 ? ', refund AED ' + money(r.paid_amount) : ', nothing paid')).slice(0, 149),
      text: 'Customer: ' + r.customer_name + ', ' + r.phone + '\n' + (r.paid_amount > 0 ? 'Refund AED ' + money(r.paid_amount) + ' in Stripe; the reservation then shows Refunded.' : 'Nothing was paid online.')});
  } catch (e) { console.warn('owner not notified: ' + e); }
