// MCP tool search_items: {query, category, lang}
function handle(req) {
  const a = req.body || {}, lang = a.lang === 'ar' ? 'ar' : 'en';
  const words = String(a.query || '').toLowerCase().split(/\s+/).filter(Boolean), cat = String(a.category || '').toLowerCase();
  const out = [];
  for (const i of db.query('SELECT * FROM items WHERE active = 1 ORDER BY id')) {
    if (cat && (i.category || '').toLowerCase() !== cat && (i.category_ar || '') !== a.category) continue;
    const hay = [i.name, i.name_ar, i.description, i.description_ar, i.category, i.category_ar, i.included].join(' ').toLowerCase();
    if (!words.every(w => hay.indexOf(w) >= 0)) continue;
    const row = {id: i.id, name: loc(i, 'name', lang), category: loc(i, 'category', lang), description: loc(i, 'description', lang),
      kind: i.mode === 'departure' ? 'tour with dated departures' : 'rental by the day', url: req.origin + '/item/' + i.id + (lang === 'ar' ? '?lang=ar' : '')};
    if (i.mode === 'departure') {
      row.price_per_adult = i.price_adult; row.price_per_child = i.price_child === null ? i.price_adult : i.price_child;
      row.duration = loc(i, 'duration', lang) || null;
    } else {
      row.price_per_day = i.price_day; row.price_per_week = i.price_week || null; row.minimum_days = i.min_days || 1;
      row.quantity_owned = i.stock || 0; row.security_deposit_at_handover = i.security_deposit || 0;
    }
    row.included = loc(i, 'included', lang) || null;
    out.push(row);
    if (out.length >= 30) break;
  }
  return {json: {currency: 'AED', prices_include_vat: true, items: out}};
}

scripts.mcp_availability:
function langOf(req) { return req.query.lang === 'ar' ? 'ar' : 'en'; }
function texts(lang) {
  const t = {};
  for (const r of db.query('SELECT key, en, ar FROM texts')) t[r.key] = (lang === 'ar' ? r.ar : r.en) || r.en;
  return t;
}
function business() { return db.query('SELECT * FROM business ORDER BY id LIMIT 1')[0]; }
function round2(n) { return Math.round(n * 100) / 100; }
function money(n) { return round2(n || 0).toFixed(2); }
function loc(row, field, lang) { return lang === 'ar' && row[field + '_ar'] ? row[field + '_ar'] : row[field]; }

// Dates are local UAE dates as text, 'YYYY-MM-DD', and times 'HH:MM'; they compare correctly as strings.
// The UAE is UTC+4 all year, so "now" in Dubai is UTC plus four hours.
function nowDubai() {
  const iso = new Date(Date.now() + 4 * 3600 * 1000).toISOString();
  return {date: iso.slice(0, 10), time: iso.slice(11, 16)};
}
// Milliseconds (UTC midnight) of a 'YYYY-MM-DD' date, or null when it is not a real date.
function parts(s) {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s || '');
  if (!m) return null;
  const ms = Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3]));
  return new Date(ms).toISOString().slice(0, 10) === s ? ms : null;
}
function addDays(s, n) { return new Date(parts(s) + n * 86400000).toISOString().slice(0, 10); }
function dayDiff(a, b) { return Math.round((parts(b) - parts(a)) / 86400000); }
const WEEKDAYS = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'];
const DAY_NAMES = {en: ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'], ar: ['الأحد', 'الاثنين', 'الثلاثاء', 'الأربعاء', 'الخميس', 'الجمعة', 'السبت']};
const MONTH_NAMES = {en: ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'],
  ar: ['يناير', 'فبراير', 'مارس', 'أبريل', 'مايو', 'يونيو', 'يوليو', 'أغسطس', 'سبتمبر', 'أكتوبر', 'نوفمبر', 'ديسمبر']};
function showDate(s, lang) {
  const ms = parts(s);
  if (ms === null) return s || '';
  const d = new Date(ms), l = lang === 'ar' ? 'ar' : 'en';
  return DAY_NAMES[l][d.getUTCDay()] + ' ' + d.getUTCDate() + ' ' + MONTH_NAMES[l][d.getUTCMonth()] + ' ' + d.getUTCFullYear();
}
// A whole number from a form or query value; def when it is missing, -1 when it is not a whole number.
function whole(v, def) {
  if (v === undefined || v === null || v === '') return def;
  const n = Number(v);
  return Number.isInteger(n) ? n : -1;
}
function errorText(t, key, n) { return (t[key] || t.error_departure).replace(/\{n\}/g, String(n || 0)); }
function lineLabel(l, lang) { return (lang === 'ar' && l.name_ar ? l.name_ar : l.name) + (l.qty > 1 ? ' × ' + l.qty : ''); }

function page(req, extra) {
  const lang = langOf(req), b = business(), qs = [];
  for (const k in req.query) if (k !== 'lang' && k !== 'error' && k !== 'n') qs.push(encodeURIComponent(k) + '=' + encodeURIComponent(req.query[k]));
  const mine = qs.concat(lang === 'ar' ? ['lang=ar'] : []);
  const base = {lang: lang, dir: lang === 'ar' ? 'rtl' : 'ltr', t: texts(lang), user: req.user, business: b,
    businessName: loc(b, 'name', lang), tagline: loc(b, 'tagline', lang), licence: b.licence || '',
    here: req.path + (mine.length ? '?' + mine.join('&') : ''),
    langUrl: req.path + '?' + qs.concat(['lang=' + (lang === 'ar' ? 'en' : 'ar')]).join('&'),
    wa: (b.whatsapp || '').replace(/[^0-9]/g, '')};
  for (const k in extra) base[k] = extra[k];
  return base;
}

// A departure row runs on its own date, or, when date is empty, on its weekdays ('daily' or e.g. 'fri,sat').
function runsOn(dep, date) {
  if (dep.date) return dep.date === date;
  const w = (dep.weekdays || 'daily').toLowerCase();
  return w.indexOf('daily') >= 0 || w.indexOf(WEEKDAYS[new Date(parts(date)).getUTCDay()]) >= 0;
}
// Nothing is counted down: seats and stock in use are added up from the reservations that hold them
// (pending, confirmed, completed, no_show), so a cancelled, failed, expired or refunded reservation frees them by itself.
function seatsTaken(depId, date, exceptId) {
  return db.query(`SELECT COALESCE(SUM(adults + children), 0) AS n FROM reservations WHERE departure_id = ? AND start_date = ? AND id <> ?
    AND status IN ('pending', 'confirmed', 'completed', 'no_show')`, depId, date, exceptId || 0)[0].n;
}
// Units of a rental item free on every day from start to end: stock minus the busiest day in that range.
// The return day counts as taken.
function rangeLeft(item, start, end, exceptId) {
  const rows = db.query(`SELECT start_date, end_date, quantity FROM reservations WHERE item_id = ? AND mode = 'range' AND id <> ?
    AND start_date <= ? AND end_date >= ? AND status IN ('pending', 'confirmed', 'completed', 'no_show')`, item.id, exceptId || 0, end, start);
  let busiest = 0;
  for (let d = start; d <= end; d = addDays(d, 1)) {
    let n = 0;
    for (const r of rows) if (r.start_date <= d && r.end_date >= d) n += r.quantity;
    if (n > busiest) busiest = n;
  }
  return (item.stock || 0) - busiest;
}
// Price of one unit for a number of days: full weeks at the weekly price when there is one, never more than one more full week.
function rentalPrice(item, days) {
  const day = item.price_day || 0;
  if (!item.price_week) return day * days;
  const weeks = Math.floor(days / 7);
  return Math.min(weeks * item.price_week + (days % 7) * day, (weeks + 1) * item.price_week);
}
function extrasFor(item) {
  return db.query(`SELECT * FROM extras WHERE active = 1 AND (item_id = ? OR (item_id IS NULL AND (category = ? OR category IS NULL OR category = ''))) ORDER BY id`,
    item.id, item.category || '');
}
// Upcoming departures of a tour within the bookable period, with seats left.
function occurrences(item, b, lang, limit) {
  const now = nowDubai(), ahead = b.days_ahead > 0 ? b.days_ahead : 60;
  const deps = db.query('SELECT * FROM departures WHERE item_id = ? AND active = 1 ORDER BY time, id', item.id);
  const taken = {};
  for (const r of db.query(`SELECT departure_id, start_date, SUM(adults + children) AS n FROM reservations WHERE item_id = ? AND mode = 'departure'
    AND start_date >= ? AND status IN ('pending', 'confirmed', 'completed', 'no_show') GROUP BY departure_id, start_date`, item.id, now.date)) {
    taken[r.departure_id + '_' + r.start_date] = r.n;
  }
  const out = [];
  for (let i = 0; i <= ahead && out.length < limit; i++) {
    const date = addDays(now.date, i);
    for (const d of deps) {
      if (!runsOn(d, date) || (i === 0 && d.time <= now.time)) continue;
      const key = d.id + '_' + date, left = d.capacity - (taken[key] || 0);
      out.push({key: key, departure_id: d.id, date: date, time: d.time, label: showDate(date, lang) + ' · ' + d.time, left: left, full: left <= 0,
        priceNum: d.price === null ? item.price_adult : d.price, price: money(d.price === null ? item.price_adult : d.price)});
    }
  }
  return out;
}

// Checks one request against the database and prices it. f holds strings as sent by the browser:
// tours: when ('<departure id>_<date>'), adults, children; rentals: start, end, qty; extras: x<extra id> = '1'.
// Returns {ok: true, lines, total, vat, online, ...} or {ok: false, error: '<texts key>', n}. Prices never come from the browser.
function quote(item, f, b, exceptId) {
  const now = nowDubai(), ahead = b.days_ahead > 0 ? b.days_ahead : 60, last = addDays(now.date, ahead);
  const en = texts('en'), ar = texts('ar');
  const q = {ok: false, complete: true, error: '', n: 0, mode: item.mode, left: 0, departure_id: null, start: '', end: '', time: '', days: 1,
    adults: 0, children: 0, qty: 1, lines: [], extras: []};
  const fail = (key, n) => { q.error = key; q.n = n || 0; return q; };
  let people = 0;
  if (item.mode === 'departure') {
    const m = /^(\d+)_(\d{4}-\d{2}-\d{2})$/.exec(f.when || '');
    if (!m) { q.complete = false; return fail('error_choose_departure'); }
    const dep = db.query('SELECT * FROM departures WHERE id = ? AND item_id = ? AND active = 1', Number(m[1]), item.id)[0];
    const date = m[2];
    if (!dep || parts(date) === null || !runsOn(dep, date) || date < now.date || date > last || (date === now.date && dep.time <= now.time)) return fail('error_departure');
    q.adults = whole(f.adults, 1); q.children = whole(f.children, 0);
    if (!(q.adults >= 1 && q.adults <= 99 && q.children >= 0 && q.children <= 99)) return fail('error_people');
    people = q.adults + q.children;
    q.departure_id = dep.id; q.start = date; q.end = date; q.time = dep.time;
    q.left = dep.capacity - seatsTaken(dep.id, date, exceptId);
    if (q.left < people) return fail('error_seats', Math.max(0, q.left));
    const adult = dep.price === null ? (item.price_adult || 0) : dep.price;
    const child = item.price_child === null ? adult : Math.min(item.price_child, adult);
    q.lines.push({name: item.name + ' – ' + en.adult, name_ar: (item.name_ar || item.name) + ' – ' + ar.adult, qty: q.adults, unit: adult, amount: round2(adult * q.adults)});
    if (q.children > 0) q.lines.push({name: item.name + ' – ' + en.child, name_ar: (item.name_ar || item.name) + ' – ' + ar.child, qty: q.children, unit: child, amount: round2(child * q.children)});
  } else {
    q.start = f.start || ''; q.end = f.end || '';
    if (!q.start || !q.end) { q.complete = false; return fail('error_dates'); }
    if (parts(q.start) === null || parts(q.end) === null || q.start < now.date || q.start > last || q.end < q.start) return fail('error_dates');
    q.days = Math.max(1, dayDiff(q.start, q.end)); // same-day return counts as one day
    if (q.days > 90) return fail('error_dates');
    if (q.days < (item.min_days || 1)) return fail('error_min_days', item.min_days);
    q.qty = whole(f.qty, 1);
    if (!(q.qty >= 1 && q.qty <= 999)) return fail('error_quantity');
    q.left = rangeLeft(item, q.start, q.end, exceptId);
    if (q.left < q.qty) return fail('error_stock', Math.max(0, q.left));
    const unit = rentalPrice(item, q.days);
    const d = ' – ' + q.days + ' ';
    q.lines.push({name: item.name + d + (q.days === 1 ? en.day : en.days), name_ar: (item.name_ar || item.name) + d + (q.days === 1 ? ar.day : ar.days),
      qty: q.qty, unit: unit, amount: round2(unit * q.qty)});
  }
  for (const x of extrasFor(item)) {
    if (f['x' + x.id] !== '1') continue;
    const times = x.per === 'person' ? (item.mode === 'departure' ? people : q.qty) : x.per === 'day' ? q.days : 1;
    q.extras.push(x.id);
    q.lines.push({name: x.name, name_ar: x.name_ar || x.name, qty: times, unit: x.price, amount: round2(x.price * times)});
  }
  let total = 0;
  for (const l of q.lines) total += l.amount;
  q.total = round2(total);
  q.vat = round2(q.total * 5 / 105); // prices include 5% VAT
  q.net = round2(q.total - q.vat);
  const percent = Math.max(0, Math.min(100, b.deposit_percent || 0));
  q.online = b.card_enabled && percent > 0 ? round2(q.total * percent / 100) : 0; // the share paid by card to secure the reservation
  q.security = item.mode === 'range' ? round2((item.security_deposit || 0) * q.qty) : 0; // collected at handover, never online
  q.ok = true;
  return q;
}
// Rows of a price summary for the item page (live, through /api/availability) and the checkout page.
function quoteRows(q, t, lang, pay) {
  const rows = q.lines.map(l => ({label: lineLabel(l, lang), value: 'AED ' + money(l.amount), cls: ''}));
  rows.push({label: t.total, value: 'AED ' + money(q.total), cls: 'total'});
  rows.push({label: t.vat_in_total, value: 'AED ' + money(q.vat), cls: 'muted'});
  if (pay && q.online > 0) {
    rows.push({label: t.pay_now, value: 'AED ' + money(q.online), cls: ''});
    rows.push({label: t.balance, value: 'AED ' + money(q.total - q.online), cls: ''});
  }
  if (q.security > 0) rows.push({label: t.security_deposit, value: 'AED ' + money(q.security), cls: 'muted'});
  return rows;
}

// MCP tool check_availability: {item, date, start, end, people, children, quantity, lang}
// Tours: the departures on date (or the next ones) with seats left and the price for the party.
// Rentals: units free from start to end and the price for that many days.
function handle(req) {
  const a = req.body || {}, lang = a.lang === 'ar' ? 'ar' : 'en', t = texts(lang), b = business();
  const i = db.query('SELECT * FROM items WHERE id = ? AND active = 1', Number(a.item))[0];
  if (!i) return {text: 'No such item; use search_items to find item ids.', status: 404};
  const url = req.origin + '/item/' + i.id + (lang === 'ar' ? '?lang=ar' : '');
  if (i.mode === 'departure') {
    const adults = whole(a.people, 1), children = whole(a.children, 0);
    let list = occurrences(i, b, lang, 400);
    if (a.date) list = list.filter(o => o.date === String(a.date));
    const departures = list.slice(0, 10).map(o => {
      const q = quote(i, {when: o.key, adults: String(adults), children: String(children)}, b, 0);
      return {date: o.date, time: o.time, seats_left: o.left, available: q.ok, price_per_adult: o.priceNum, total_price: q.ok ? q.total : null,
        pay_online_now: q.ok ? q.online : null};
    });
    return {json: {item: loc(i, 'name', lang), kind: 'tour', adults: adults, children: children, available: departures.some(d => d.available), departures: departures,
      currency: 'AED', prices_include_vat: true, note: departures.length ? 'Extras such as hotel pickup are chosen on the booking page.' : 'No departure on that date within the bookable period.',
      book_at: url}};
  }
  if (!a.start || !a.end) return {text: 'For a rental give start and end as YYYY-MM-DD.', status: 400};
  const q = quote(i, {start: String(a.start), end: String(a.end), qty: String(whole(a.quantity, 1))}, b, 0);
  const out = {item: loc(i, 'name', lang), kind: 'rental', start: String(a.start), end: String(a.end), quantity: whole(a.quantity, 1), available: q.ok,
    stock_left: q.ok ? q.left : q.n, currency: 'AED', prices_include_vat: true, book_at: url};
  if (q.ok) {
    out.days = q.days; out.total_price = q.total; out.pay_online_now = q.online; out.security_deposit_at_handover = q.security;
  } else {
    out.reason = errorText(t, q.error, q.n);
  }
  return {json: out};
}

