function page(req, extra) {
  const lang = langOf(req), b = business(), qs = [];
  for (const k in req.query) if (k !== 'lang' && k !== 'error' && k !== 'n') qs.push(encodeURIComponent(k) + '=' + encodeURIComponent(req.query[k]));
  const mine = qs.concat(lang === 'ar' ? ['lang=ar'] : []);
  const base = {lang: lang, dir: lang === 'ar' ? 'rtl' : 'ltr', t: texts(lang), user: req.user, business: b,
    businessName: loc(b, 'name', lang), tagline: loc(b, 'tagline', lang), licence: b.licence || '',
    here: req.path + (mine.length ? '?' + mine.join('&') : ''),
    langUrl: req.path + '?' + qs.concat(['lang=' + (lang === 'ar' ? 'en' : 'ar')]).join('&'),
    wa: (b.whatsapp || '').replace(/[^0-9]/g, '')};
